import json,copy
from pathlib import Path
P=json.loads(Path('packet.json').read_text());S={e['source_id']:e for e in P['entries']}
A=json.loads(Path('annotation.json').read_text());U={u['unit_id']:u for u in A['units']}
Path('annotation.after_mechanical.json').write_bytes(Path('annotation.json').read_bytes())
log=json.loads(Path('repair_log.json').read_text());changes=log['changes']
def ev(s,q,start=0):
 i=S[s]['text'].index(q,start);return {'source_id':s,'span':{'start':i,'end':i+len(q),'quote':q}}
def eu(k):return {'source_id':U[k]['source_id'],'span':copy.deepcopy(U[k]['span'])}
def change(obj,key,value,ident,reason,meaning=False,epistemic=False):
 old=copy.deepcopy(obj[key]);obj[key]=value
 if old==value:return
 changes.append({'change_id':f'S{sum(x["stage"]=="self_review" for x in changes)+1:02d}','stage':'self_review','affected':ident,'field':str(key),'before':old,'after':copy.deepcopy(value),'meaning_changes':meaning,'epistemic_correction':epistemic,'reason':reason})
def comp(k,sym):return next(c for c in U[k]['components'] if c['symbol']==sym)
# Correct predicate-specific occurrences, not just repeated referents.
c=comp('occasionally_rebase','A');change(c,'evidence',[ev(U['occasionally_rebase']['source_id'],'we',U['leave_open']['span']['start'])],'occasionally_rebase.A','The shared subject is we could leave/rebase, not the earlier we in the historical as-we-have-done clause.',epistemic=True)
for k in ['remove23','explain24']:
 c=comp(k,'A');start=S[U[k]['source_id']]['text'].index('you will either');change(c,'evidence',[ev(U[k]['source_id'],'you',start)],k+'.A','Use the subject of the operative need-to predicate rather than the subject of want in the activation condition.',epistemic=True)
 change(U[k],'speech_act','asserted',k,'Future need expresses a declarative conditional requirement. The normative force and alternatives are unchanged.')
c=comp('b_method','Cac');change(c,'basis','context_inferred','b_method.Cac','The comparison supplies recurrence; treating it as activation of reconstructed repeat is an inferred grammatical role.',epistemic=True);change(c,'occurrence_role','semantic_inference','b_method.Cac','Declare the inferred activation role explicitly.',epistemic=True);change(c,'inference_note','The phrase compares the present procedure with every release; recurrence as the activation of reconstructed repeat is inferred, not a literal conditional clause.','b_method.Cac','Explain the transformed comparison role.',epistemic=True)
# Keep the explicitly simplified procedure, rather than implying unchanged repetition.
c=comp('b_method','Bdir');change(c,'text','current simplified procedure for adding a previous release','b_method.Bdir','The remainder of the same sentence explicitly relaxes a former tag-list-editing step; retain that qualification.',meaning=True)
change(c,'evidence',c['evidence']+[ev('pr26586:body','only a little simpler now')],'b_method.Bdir','Anchor the current-procedure qualification rather than relying only on the title.',meaning=True)
change(c,'inference_note','The nominal phrase becomes the target of reconstructed repeat. The PR title identifies release addition, while only a little simpler now and the separately linked negative-need clause qualify the current procedure. No unchanged copying of all historical steps is inferred.','b_method.Bdir','Preserve present versus historical method identity and the eliminated editing step.',meaning=True)
i=copy.deepcopy(U['b_method']['institution']);i['standing']='disputed';i['dispute_present']=True;i['evidence']+=[eu('concept_nack'),eu('b_notags')];i['rationale']='The author presents this addition as an instance of a recurrent release-addition method, with a newly simplified tag-fetching step. The conceptual NACK challenges applying that method to v24 in this case; it does not prove rejection of every earlier instance or an authorized veto. The historical patches support examples rather than a binding obligation.'
change(U['b_method'],'institution',i,'b_method','The existing challenge relation requires recording the evidenced dispute over application of this recurring method.',meaning=True)
# A technical counterargument addresses the specific wallet rationale, not #25717 alone.
q='On the wallet side this version added watch-only miniscript support (which last time I checked caused problems when downgrading).'
w=copy.deepcopy(U['no_miniscript_test']);w.update({'unit_id':'wallet_support_reason','source_id':'pr26586:comments:4','span':ev('pr26586:comments:4',q)['span'],'speech_act':'asserted','confidence':'plausible','alternative_interpretation':'This is a technical reason advanced for inclusion, not a separate instruction or proof that the current test exercises miniscript.','uncertainty_reason':'The participant reports the support change and remembered downgrade problem; neither is independently tested in this packet.'});w['institution']['rationale']='Contextual wallet-feature rationale for the addition. The next comment challenges its relevance to the specific test, not the existence of the feature.';w['institution']['evidence']=[ev('pr26586:comments:4',q)]
A['units'].insert(A['units'].index(U['add_v24'])+1,w);U[w['unit_id']]=w
changes.append({'change_id':f'S{sum(x["stage"]=="self_review" for x in changes)+1:02d}','stage':'self_review','affected':'wallet_support_reason','field':'new context unit','before':None,'after':copy.deepcopy(w),'meaning_changes':True,'epistemic_correction':False,'reason':'Create the actual challenged rationale as a distinct relation endpoint instead of attributing a wallet-test correction to the separate #25717 justification.'})
for i,r in enumerate(A['relations']):
 if r['from_unit_id']=='no_miniscript_test' and r['to_unit_id']=='add_v24':
  nr=copy.deepcopy(r);nr['to_unit_id']='wallet_support_reason';nr['evidence']=[eu('no_miniscript_test'),eu('wallet_support_reason')];nr['rationale']='The correction that this test does not exercise watch-only miniscript challenges the relevance of the preceding wallet-feature rationale. It does not contradict #25717 as a separate justification or deny that the feature exists.';change(A['relations'],i,nr,'relation:no_miniscript_test','Narrow the target of the technical challenge to its supported rationale.',meaning=True)
 if r['from_unit_id']=='verify_assumption' and r['type']=='uptake':
  nr=copy.deepcopy(r);nr['from_unit_id']='explain24';nr['to_unit_id']='verify_assumption';change(A['relations'],i,nr,'relation:explain24->verify_assumption','Uptake must point from the initiating request to its attributable response.',meaning=True)
 if (r['from_unit_id'],r['to_unit_id']) in [('release_concern','hold_off'),('status_ping','tested_ack')]:
  nr=copy.deepcopy(r);nr['type']='temporal';first=S[U[r['from_unit_id']]['source_id']]['timestamp'];second=S[U[r['to_unit_id']]['source_id']]['timestamp'];nr['rationale']=f'Supplied source-entry timestamps order these recorded acts ({first} before {second}). The initiating context is not coded as a request/proposal; this relation asserts only order, not a response obligation or causation.';change(A['relations'],i,nr,'relation:'+r['from_unit_id'],'Avoid representing an unspecified concern or context-only ping as an institutional initiating request.',meaning=True)
 if r['from_unit_id']=='need_rebase' and r['type']=='uptake':
  nr=copy.deepcopy(r);nr['rationale']='The report specifically names rebasing on master, corresponding to the earlier rebase request. No supplied outcome for #26589 verifies the request’s after-#26589 qualification; this is partial, contextual uptake rather than proof that the full requirement was met.';change(A['relations'],i,nr,'relation:need_rebase','Preserve the unresolved dependency qualification in the uptake claim.',meaning=True)
newrel={'from_unit_id':'b_notags','to_unit_id':'b_method','type':'clarifies','basis':'context_inferred','rationale':'The same body explains that automatic fetching makes the current recurring procedure simpler by removing the need to extend tag lists. This limits the reconstructed repeat action to the current procedure.','evidence':[eu('b_method'),ev('pr26586:body','only a little simpler now: thanks to #25650, the previous release fetch script defaults to downloading/building the necessary tags'),eu('b_notags')],'logic_scope':'not_applicable'}
A['relations'].append(newrel);changes.append({'change_id':f'S{sum(x["stage"]=="self_review" for x in changes)+1:02d}','stage':'self_review','affected':'relation:b_notags->b_method','field':'new clarifies relation','before':None,'after':copy.deepcopy(newrel),'meaning_changes':True,'epistemic_correction':False,'reason':'Link the simplified-step qualification to the reconstructed recurring procedure rather than leaving their scope unconnected.'})
# Do not promote a report of rebasing into proof of the after-other-PR condition.
r=copy.deepcopy(U['need_rebase']['institution']['recognition']);r[0]['target']='broader_proposal';r[0]['rationale']='The author reports rebasing this PR on master, but does not identify #26589 or verify fulfillment of the request’s dependency condition. The report is scoped to maintenance of the broader contribution, not verified implementation of the full qualified proposition.';change(U['need_rebase']['institution'],'recognition',r,'need_rebase.recognition','Broaden report scope because a material dependency condition remains unverified.',meaning=True)
d=copy.deepcopy(U['need_rebase']['disposition_events']);d[0]['target']='broader_proposal';d[0]['rationale']='Rebasing is reported for the PR. The report does not verify that the specified after-#26589 dependency was met, so the full conditional requirement is not marked implemented.';change(U['need_rebase'],'disposition_events',d,'need_rebase.disposition','Keep action report separate from fulfillment of the entire qualified request.',meaning=True)
# Complete attribution without an unsupported causal verb.
m=A['episode_summary']['mechanisms'][0];change(m,'claim','A conceptual objection to adding v24 is followed by an addressed argument for including every major release and a particular justification for v24. Review then contrasted a latest-per-missing-feature criterion with a minimum recent-non-EOL wallet-testing baseline. The author offered verification of both versions as a reason, and Sjors later tentatively agreed with the quoted baseline. This is a supported argumentative sequence, not proof that any criterion caused integration.','mechanism:reason_giving','Replace prompted with a source-supported addressed sequence, without asserting causal identification.',meaning=True)
m=A['episode_summary']['mechanisms'][1];change(m,'claim','The conditional request to update the contribution to 24.0.1 corresponds to the author’s subsequent explicit update report. A separate earlier rebase request also corresponds to the report of rebasing on master, but the packet does not verify its after-#26589 qualification. The source supports an action/request-report sequence without verifying successful downloads or causal dependence on either comment.','mechanism:review_coordination','Preserve the requested dependency and limit the apparent implementation claim.',meaning=True)
for sc in A['entry_screening']:
 if sc['source_id']=='pr26586:comments:4':change(sc,'unit_ids',[u['unit_id'] for u in A['units'] if u['source_id']==sc['source_id']],'screening:comments:4','Register the new contextual rationale endpoint. The candidate disposition is unchanged.')
Path('annotation.json').write_text(json.dumps(A,ensure_ascii=False,indent=2)+'\n')
Path('annotation.final.json').write_bytes(Path('annotation.json').read_bytes())
log['self_review_passes']=1;log['notes']='Mechanical corrections and one complete source-based review are separately recorded. Original packet, codebook, schema, checker, and first-complete annotation are unchanged.'
Path('repair_log.json').write_text(json.dumps(log,ensure_ascii=False,indent=2)+'\n')
print(json.dumps({'units':len(A['units']),'statements':sum(u['record_role']=='statement' for u in A['units']),'relations':len(A['relations']),'logged_changes':len(changes)},indent=2))
